import { NextResponse } from 'next/server';

export async function GET() {
  // Simulate fetching user preferences
  const preferences = {
    theme: Math.random() > 0.5 ? 'dark' : 'light',
    notifications: true,
    language: 'en-US',
    lastLogin: new Date().toISOString(),
  };

  return NextResponse.json(preferences, {
    headers: {
      'Cache-Control': 'no-store, max-age=0',
    },
  });
}

import { headers } from 'next/headers';

interface UserPreferences {
  theme: string;
  notifications: boolean;
  language: string;
  lastLogin: string;
}

export default async function UserDashboard() {
  const headersList = await headers();
  const host = headersList.get('host') || 'localhost:3000';
  const protocol = host.includes('localhost') ? 'http' : 'https';

  let preferences: UserPreferences | null = null;

  try {
    const res = await fetch(`${protocol}://${host}/api/user/preferences`, {
      cache: 'no-store', // Ensure data is fetched fresh on each request
    });

    if (res.ok) {
      preferences = await res.json();
    } else {
      console.error('Failed to fetch preferences:', res.status, res.statusText);
    }
  } catch (error) {
    console.error('Error fetching user preferences:', error);
  }

  if (!preferences) {
    return (
      <div>
        <h2>User Dashboard</h2>
        <p>Unable to load user preferences at this time.</p>
      </div>
    );
  }

  return (
    <div>
      <h2>User Dashboard</h2>
      <p><strong>Theme:</strong> {preferences.theme}</p>
      <p><strong>Notifications:</strong> {preferences.notifications ? 'On' : 'Off'}</p>
      <p><strong>Language:</strong> {preferences.language}</p>
      <p><strong>Last Login:</strong> {preferences.lastLogin}</p>
    </div>
  );
}

